css:
.lock-button {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background-color: rgb(20, 20, 20);
  border: none;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0px 0px 20px rgba(0, 0, 0, 0.164);
  cursor: pointer;
  transition-duration: 0.3s;
  overflow: hidden;
  position: relative;
  text-decoration: none !important;
}

.lock-svgIcon {
  width: 17px;
  transition-duration: 0.3s;
}

.lock-svgIcon path {
  fill: white;
}

.lock-button:hover {
  border-radius: 50px;
  transition-duration: 0.3s;
  background-color: rgb(255, 69, 69);
  align-items: center;
}

.lock-button:hover .lock-svgIcon {
  width: 20px;
  transition-duration: 0.3s;
  -webkit-transform: rotate(360deg);
}

.lock-button::before {
  display: none;
  color: white;
  transition-duration: 0.3s;
}

.lock-button:hover::before {
  display: block;
  opacity: 1;
  transform: translateY(0px);
  transition-duration: 0.3s;
}
